-- LEGION — les métiers ÉCRITS, modèle par modèle.
--
-- Beau, 22/09: « 8 métiers pour un studio de cinéma ? Il faut spécifier: un
-- cabinet de conseil, c'est quoi le concept, combien de personnes, qui y
-- travaille, un petit, un grand comme McKinsey, Wall Street. » Il a raison:
-- le catalogue GitHub ne couvre que le logiciel et la direction. Le reste,
-- on l'écrit ici, à la main, avec un mandat par poste.
--
-- Additif: deux colonnes sur les modèles, des lignes en plus sur les postes.
-- Un poste écrit ici est TENU (a_ecrire = false): son mandat est sa fiche.

alter table public.studio_modeles add column if not exists concept text;
alter table public.studio_modeles add column if not exists effectifs text;

update public.studio_modeles set concept = 'Un cabinet vend du jugement. Une question de direction, une équipe de mission de trois à six personnes pendant huit à douze semaines, un mémo qui tranche. La pyramide: l''associé vend et répond du résultat; le directeur de mission conduit l''équipe; consultants et analystes font les entretiens, les chiffres et les pages. Autour: des experts par pratique et par secteur, la recherche, et les fonctions support.', effectifs = 'Boutique: 5 à 30. Cabinet régional: 100 à 500. Grand cabinet mondial: plusieurs dizaines de milliers (McKinsey ≈ 45 000).' where cle = 'conseil';
update public.studio_modeles set concept = 'Une salle de marché achète et vend, pour des clients ou pour compte propre. Le front office prend les positions: traders, vendeurs, structureurs, gérants, quants. Le middle office les surveille: risque, conformité, contrôle. Le back office les règle: opérations, trésorerie, comptabilité. La recherche éclaire tout le monde, la technologie fait tourner la machine à la milliseconde.', effectifs = 'Fonds indépendant: 5 à 50. Société de gestion: 200 à 2 000. Grande banque d''investissement: plusieurs milliers sur les seuls marchés.' where cle = 'marche';
update public.studio_modeles set concept = 'Un studio fabrique des films et des séries en quatre temps. Développement: l''idée devient un scénario financé. Pré-production: tout est dessiné, planifié, casté. Production: on tourne ou on anime. Post-production: montage, effets, son, étalonnage. Autour, la distribution et le marketing trouvent le public. Un long métrage d''animation occupe des centaines de personnes pendant plusieurs années; une série, une équipe de cinquante à cent cinquante par saison.', effectifs = 'Studio indépendant: 5 à 40. Studio de série: 100 à 300. Grand studio d''animation: plus d''un millier.' where cle = 'cinema';
update public.studio_modeles set concept = 'Un cabinet répond à une question de droit par une réponse engagée. Il s''organise par pratiques — sociétés, contrats, propriété intellectuelle, travail, fiscal, données, contentieux — et, pour l''expansion, par pays: l''expert d''un pays connaît ses règles d''immatriculation, de fiscalité, d''emploi et de protection des consommateurs. La pyramide: associés, collaborateurs seniors, collaborateurs, juristes, parajuristes.', effectifs = 'Cabinet de niche: 3 à 20. Cabinet d''affaires national: 50 à 300. Cabinet mondial: plusieurs milliers d''avocats dans 30 à 50 pays.' where cle = 'juridique';
update public.studio_modeles set concept = 'Un laboratoire pose des questions et y répond par la méthode: lire ce qui existe, formuler une hypothèse, concevoir l''expérience, la mener, analyser, écrire, se faire relire. Le directeur scientifique fixe le programme; chaque chercheur principal mène une ligne; post-doctorants, doctorants et ingénieurs font le travail; statisticiens et relecteurs empêchent de se raconter des histoires.', effectifs = 'Équipe: 3 à 15. Laboratoire: 30 à 150. Institut: 500 à 3 000.' where cle = 'recherche';
update public.studio_modeles set concept = 'Une agence fait venir des clients et les garde. Le planneur comprend le marché, la création fabrique le message, les canaux le diffusent — recherche, réseaux, publicité, e-mail, partenaires — et la donnée dit ce qui a marché. Les ventes transforment l''intérêt en contrat, le succès client le renouvelle.', effectifs = 'Agence de quartier: 3 à 15. Agence nationale: 50 à 300. Réseau mondial: plusieurs milliers.' where cle = 'croissance';
update public.studio_modeles set concept = 'Un studio produit conçoit, construit, livre et fait vivre un logiciel. Le produit décide quoi faire et pourquoi; le design décide comment ça se présente; l''ingénierie le construit; la qualité vérifie; l''infrastructure fait tourner; la donnée mesure; la sécurité protège. Des équipes de six à dix, chacune responsable d''un morceau de bout en bout.', effectifs = 'Studio indépendant: 3 à 20. Scale-up: 100 à 500. Grand éditeur: plusieurs milliers d''ingénieurs.' where cle = 'produit';

