-- Les postes qu'on avait marqués « à écrire » dans 0136 ont maintenant un
-- mandat qui suffit: on les allume.
update public.studio_modele_postes set a_ecrire = false where a_ecrire and mandat is not null and length(mandat) > 10;

-- Le catalogue contenait un gabarit (« Agent Name ») pris pour un agent.
delete from public.studio_modele_postes where agent_cle = 'agent-name';

-- Les postes venus du catalogue « c-level » portaient le préfixe technique « Cs ».
update public.studio_modele_postes set poste = regexp_replace(poste, '^Cs ', '') where poste like 'Cs %';

-- Un directeur par département suffit: dans un modèle, un poste directeur
-- reste unique, les nouveaux directeurs écrits ici ne doublent pas ceux de 0136.
